import { Fragment, useId, useState } from "react"

export type PricingTier = {
  id: string
  name: string
  blurb: string
  /** Price per month when billed monthly. Per seat when `perSeat`. `null` means "talk to us". */
  monthly: number | null
  perSeat?: boolean
  featured?: boolean
  cta: string
  /** Lead line above the feature list, e.g. "Everything in Pro, plus". */
  lead?: string
  features: string[]
}

export type PricingCompareRow = { group?: string; label: string; values: (boolean | string)[] }

export type TieredPricingTableProps = {
  tiers?: PricingTier[]
  compare?: PricingCompareRow[]
  /** Fraction off for yearly billing. */
  yearlyDiscount?: number
  currency?: string
  heading?: string
  sub?: string
  onSelect?: (tier: string, plan: { billing: "monthly" | "yearly"; seats: number; total: number | null }) => void
  className?: string
}

