// #region pricing
/** Monthly-equivalent price for a tier, after the yearly discount and seats. Rounded to whole units. */
export function priceFor(monthly: number | null, yearly: boolean, discount: number, seats = 1) {
  if (monthly === null) return null
  const unit = yearly ? monthly * (1 - discount) : monthly
  return Math.round(unit) * Math.max(1, seats)
}

/** What lands on the invoice: the monthly-equivalent times 12 when billed yearly. */
export function billedTotal(monthly: number | null, yearly: boolean, discount: number, seats = 1) {
  const p = priceFor(monthly, yearly, discount, seats)
  return p === null ? null : yearly ? p * 12 : p
}

export function clampSeats(n: number, min = 1, max = 500) {
  if (!Number.isFinite(n)) return min
  return Math.min(max, Math.max(min, Math.round(n)))
}

export function money(n: number) {
  return n.toLocaleString("en-US")
}
// #endregion

function Odometer({ value }: { value: string }) {
  const chars = value.split("")
  return (
    <span className="tpt-odo" aria-hidden="true">
      {chars.map((c, i) => {
        const k = chars.length - i
        if (!/\d/.test(c))
          return (
            <span key={"s" + k} style={{ width: ".25em" }}>
              {c}
            </span>
          )
        return (
          <span key={"d" + k} className="tpt-col" style={{ ["--tpt-d" as string]: k }}>
            <span style={{ transform: "translateY(" + -+c + "em)" }}>
              {"0123456789".split("").map((d) => (
                <b key={d}>{d}</b>
              ))}
            </span>
          </span>
        )
      })}
    </span>
  )
}

const Arrow = () => (
  <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
    <path d="M3 8h10m0 0-3.5-3.5M13 8l-3.5 3.5" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
)

export default function TieredPricingTable({
  tiers = TIERS,
  compare = COMPARE,
  yearlyDiscount = 0.2,
  currency = "$",
  heading = "Pricing that grows with you",
  sub = "Start free, upgrade when it clicks. Every plan includes unlimited viewers and a 30-day money-back promise.",
  onSelect,
  className = "",
}: TieredPricingTableProps) {
  const [yearly, setYearly] = useState(true)
  const [seats, setSeats] = useState(5)
  const [open, setOpen] = useState(false)
  const [picked, setPicked] = useState("")
  const uid = useId()

  const setBilling = (y: boolean) => setYearly(y)
  const pct = Math.round(yearlyDiscount * 100)

  return (
    <section className={"tpt-root " + className} aria-labelledby={uid + "h"}>
      <style>{CSS}</style>
      <div className="tpt-top">
        <div className="tpt-eyebrow">
          <i aria-hidden="true" />
          Pricing
          <i aria-hidden="true" />
        </div>
        <h2 className="tpt-h" id={uid + "h"}>
          {heading}
        </h2>
        <p className="tpt-sub">{sub}</p>
        <div
          className="tpt-toggle"
          role="radiogroup"
          aria-label="Billing period"
          data-yearly={yearly}
          onKeyDown={(e) => {
            if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
              e.preventDefault()
              setBilling(e.key === "ArrowRight")
              ;(e.currentTarget.querySelectorAll("button")[e.key === "ArrowRight" ? 1 : 0] as HTMLButtonElement).focus()
            }
          }}
        >
          <span className="tpt-thumb" aria-hidden="true" />
          <button type="button" role="radio" aria-checked={!yearly} tabIndex={yearly ? -1 : 0} className="tpt-opt" onClick={() => setBilling(false)}>
            Monthly
          </button>
          <button type="button" role="radio" aria-checked={yearly} tabIndex={yearly ? 0 : -1} className="tpt-opt" onClick={() => setBilling(true)}>
            Yearly <span className="tpt-save">−{pct}%</span>
          </button>
        </div>
      </div>

      <div className="tpt-grid">
        {tiers.map((t, i) => {
          const n = t.perSeat ? seats : 1
          const p = priceFor(t.monthly, yearly, yearlyDiscount, n)
          const full = priceFor(t.monthly, false, 0, n)
          const total = billedTotal(t.monthly, yearly, yearlyDiscount, n)
          const done = picked === t.id
          return (
            <article key={t.id} className="tpt-card" data-featured={!!t.featured} style={{ ["--tpt-i" as string]: i }} aria-labelledby={uid + t.id}>
              {t.featured && (
                <span className="tpt-flag">
                  <svg width="11" height="11" viewBox="0 0 12 12" aria-hidden="true">
                    <path d="M6 .8l1.5 3.3 3.6.4-2.7 2.4.8 3.6L6 8.6 2.8 10.5l.8-3.6L.9 4.5l3.6-.4L6 .8Z" fill="currentColor" />
                  </svg>
                  Most popular
                </span>
              )}
              <h3 className="tpt-name" id={uid + t.id}>
                <span className="tpt-dot" aria-hidden="true" />
                {t.name}
              </h3>
              <p className="tpt-blurb">{t.blurb}</p>
              <div className="tpt-price">
                {p === null ? (
                  <span className="tpt-talk">Let's talk</span>
                ) : (
                  <>
                    <span className="tpt-cur" aria-hidden="true">
                      {currency}
                    </span>
                    <Odometer value={money(p)} />
                    <span className="tpt-sr">
                      {currency}
                      {money(p)} per month{t.perSeat ? " for " + n + " seats" : ""}
                      {yearly && p ? ", billed yearly" : ""}
                    </span>
                    <span className="tpt-per" aria-hidden="true">
                      {yearly && full !== null && full > p && <span className="tpt-was">{currency + money(full)}</span>}
                      {p === 0 ? "forever" : "/ month"}
                    </span>
                  </>
                )}
              </div>
              <p className="tpt-note">
                {total === null || total === 0 ? (t.perSeat ? "" : "No card required") : yearly ? (
                  <>
                    {currency + money(total)} billed yearly · <b>save {currency + money((full || 0) * 12 - total)}</b>
                  </>
                ) : (
                  "Billed monthly · cancel anytime"
                )}
              </p>
              {t.perSeat && (
                <div className="tpt-seats">
                  <label htmlFor={uid + "seats"}>
                    Seats · {currency}
                    {priceFor(t.monthly, yearly, yearlyDiscount, 1)} each
                  </label>
                  <button type="button" className="tpt-step" aria-label="Remove a seat" disabled={seats <= 1} onClick={() => setSeats((s) => clampSeats(s - 1))}>
                    <svg width="10" height="10" viewBox="0 0 10 10" aria-hidden="true">
                      <path d="M2 5h6" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
                    </svg>
                  </button>
                  <input
                    id={uid + "seats"}
                    className="tpt-seat-in"
                    type="number"
                    inputMode="numeric"
                    min={1}
                    max={500}
                    value={seats}
                    onChange={(e) => setSeats(clampSeats(parseInt(e.target.value, 10)))}
                  />
                  <button type="button" className="tpt-step" aria-label="Add a seat" disabled={seats >= 500} onClick={() => setSeats((s) => clampSeats(s + 1))}>
                    <svg width="10" height="10" viewBox="0 0 10 10" aria-hidden="true">
                      <path d="M2 5h6M5 2v6" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
                    </svg>
                  </button>
                </div>
              )}
              <button
                type="button"
                className="tpt-cta"
                data-done={done}
                onClick={() => {
                  setPicked(t.id)
                  onSelect?.(t.id, { billing: yearly ? "yearly" : "monthly", seats: n, total })
                }}
              >
                {done ? (
                  <>
                    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
                      <path d="M3.5 8.5l3 3 6-6.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                    </svg>
                    {t.name} selected
                  </>
                ) : (
                  <>
                    {t.cta}
                    <Arrow />
                  </>
                )}
              </button>
              {t.lead && <p className="tpt-lead">{t.lead}</p>}
              <ul className="tpt-feats" style={t.lead ? undefined : { marginTop: 22 }}>
                {t.features.map((f, j) => (
                  <li key={f} style={{ ["--tpt-j" as string]: j }}>
                    <span className="tpt-ck" aria-hidden="true">
                      <svg width="10" height="10" viewBox="0 0 16 16" fill="none">
                        <path d="M3.5 8.5l3 3 6-6.5" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" />
                      </svg>
                    </span>
                    {f}
                  </li>
                ))}
              </ul>
            </article>
          )
        })}
      </div>

      <div className="tpt-ent">
        <div>
          <h4>Enterprise</h4>
          <p>Volume pricing, a dedicated region, SCIM and a named success engineer.</p>
        </div>
        <button type="button" className="tpt-cta" onClick={() => onSelect?.("enterprise", { billing: yearly ? "yearly" : "monthly", seats, total: null })}>
          Talk to sales
          <Arrow />
        </button>
      </div>

      {compare.length > 0 && (
        <>
          <button type="button" className="tpt-more" aria-expanded={open} aria-controls={uid + "cmp"} onClick={() => setOpen((o) => !o)}>
            {open ? "Hide" : "Compare all"} features
            <svg width="12" height="12" viewBox="0 0 12 12" fill="none" aria-hidden="true">
              <path d="M3 4.5l3 3 3-3" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </button>
          <div className="tpt-fold" data-open={open} id={uid + "cmp"}>
            <div>
              <div className="tpt-scroll">
                <table className="tpt-cmp">
                  <caption className="tpt-sr">Feature comparison</caption>
                  <thead>
                    <tr>
                      <th scope="col">
                        <span className="tpt-sr">Feature</span>
                      </th>
                      {tiers.map((t) => (
                        <th key={t.id} scope="col" data-featured={!!t.featured}>
                          {t.name}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {compare.map((r) => (
                      <Fragment key={r.label}>
                        {r.group && (
                          <tr className="tpt-grp">
                            <th scope="colgroup" colSpan={tiers.length + 1}>
                              {r.group}
                            </th>
                          </tr>
                        )}
                        <tr>
                          <th scope="row" style={{ fontWeight: 400 }}>
                            {r.label}
                          </th>
                          {tiers.map((t, i) => {
                            const v = r.values[i]
                            return (
                              <td key={t.id} data-featured={!!t.featured}>
                                {v === true ? (
                                  <span className="tpt-ck" style={{ display: "inline-grid" }}>
                                    <svg width="10" height="10" viewBox="0 0 16 16" fill="none" aria-hidden="true">
                                      <path d="M3.5 8.5l3 3 6-6.5" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" />
                                    </svg>
                                    <span className="tpt-sr">Included</span>
                                  </span>
                                ) : v === false || v === undefined ? (
                                  <>
                                    <span className="tpt-dash" aria-hidden="true" />
                                    <span className="tpt-sr">Not included</span>
                                  </>
                                ) : (
                                  v
                                )}
                              </td>
                            )
                          })}
                        </tr>
                      </Fragment>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </>
      )}
    </section>
  )
}
